import { useCallback, useEffect, useRef, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import QRCode from 'qrcode'
import { BrowserQRCodeReader } from '@zxing/browser'
import type { IScannerControls } from '@zxing/browser'
import { Link, Navigate, NavLink, Outlet, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import { api } from './api'
import type { Complaint, ResidentLocation, User } from './api'
import { BinEvacuationHistory, ManagedAreaFees, ManagedLocationsPanel, PropertyRegistrationPanel } from './Geographic'
import { AdminActivityFeed, AdminDevicesConsole, OperationsContainerConsole } from './IoTConsole'

function App() {
  const [user, setUser] = useState<User | null>(null)
  const [authReady, setAuthReady] = useState(false)
  useEffect(() => { api.me().then(({ user }) => setUser(user)).catch(() => setUser(null)).finally(() => setAuthReady(true)) }, [])
  const signOut = async () => { await api.logout().catch(() => undefined); setUser(null) }
  const saveUser = (next: User) => setUser(next)
  return <Routes>
    <Route path="/" element={<PublicLayout user={user} />}><Route index element={<Home />} /><Route path="services" element={<Services />} /><Route path="service-updates" element={<Updates />} /><Route path="login" element={<AuthPage mode="login" saveUser={saveUser} />} /><Route path="register" element={<AuthPage mode="register" saveUser={saveUser} />} /><Route path="forgot-password" element={<ForgotPassword/>} /><Route path="reset-password" element={<ResetPassword/>} /></Route>
    <Route path="/dashboard" element={<Private ready={authReady} user={user}><CitizenLayout user={user} signOut={signOut} /></Private>}>
      <Route index element={<CitizenHome />} /><Route path="complaints" element={<ComplaintList />} /><Route path="complaints/new" element={<ComplaintForm />} /><Route path="complaints/:reference" element={<ComplaintDetails />} /><Route path="payments" element={<Payments />} /><Route path="profile" element={<Profile user={user} saveUser={saveUser} />} />
    </Route>
    <Route path="/receipts/:reference" element={<Private ready={authReady} user={user}><ReceiptView/></Private>} />
    <Route path="*" element={<NotFound />} />
  </Routes>
}

function Private({ ready, user, children }: { ready: boolean; user: User | null; children: ReactNode }) {
  if (!ready) return <Loading />
  if (!user) return <Navigate to="/login" replace />
  return user.role === 'citizen' ? <>{children}</> : <Navigate to="/" replace />
}

export function ManagementApp() { return <InternalApp workspace="operations" /> }
export function AdminApp() { return <InternalApp workspace="admin" /> }

function InternalApp({ workspace }: { workspace: 'operations' | 'admin' }) {
  const [user, setUser] = useState<User | null>(null)
  const [authReady, setAuthReady] = useState(false)
  useEffect(() => { api.staffMe().then(x => setUser(x.user)).catch(() => setUser(null)).finally(() => setAuthReady(true)) }, [])
  const signOut = async () => { await api.staffLogout().catch(() => undefined); setUser(null) }
  const role = workspace === 'admin' ? 'system_administrator' : 'operations_manager'
  const landing = workspace === 'admin' ? '/admin' : '/operations'
  return <Routes>
    <Route path="/login" element={<InternalLogin ready={authReady} user={user} saveUser={setUser} workspace={workspace} />} />
    <Route path={`${landing}/*`} element={<InternalRoleGate ready={authReady} user={user} role={role}><StaffLayout user={user} signOut={signOut} type={workspace} /></InternalRoleGate>} />
    <Route path="*" element={!authReady ? <Loading /> : <Navigate to={user?.role === role ? landing : '/login'} replace />} />
  </Routes>
}

function InternalRoleGate({ ready, user, role, children }: { ready: boolean; user: User | null; role: string; children: ReactNode }) {
  if (!ready) return <Loading />
  if (!user) return <Navigate to="/login" replace />
  if (user.role === role) return <>{children}</>
  return <section className="internal-denied"><span className="internal-lock">⌑</span><p className="eyebrow">Organization portal</p><h1>Access not granted</h1><p>This staff account does not have permission to open this workspace. Contact your system administrator if you need access.</p><Link to="/operations" className="button button-outline">Open operations workspace</Link></section>
}

function InternalLogin({ ready, user, saveUser, workspace }: { ready: boolean; user: User | null; saveUser: (u: User) => void; workspace: 'operations' | 'admin' }) {
  const navigate = useNavigate()
  const role = workspace === 'admin' ? 'system_administrator' : 'operations_manager'
  const landing = workspace === 'admin' ? '/admin' : '/operations'
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  useEffect(() => { if (ready && user?.role === role) navigate(landing, { replace: true }) }, [ready, user, navigate, role, landing])
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setBusy(true)
    setError('')
    const data = new FormData(event.currentTarget)
    try {
      const result = await api.staffLogin(String(data.get('email')), String(data.get('password')))
      if (result.user.role !== role) throw new Error('This account is not assigned to this workspace.')
      saveUser(result.user)
      navigate(landing, { replace: true })
    } catch {
      setError('Staff sign-in could not be verified. Check your details or contact your system administrator.')
    } finally { setBusy(false) }
  }
  if (!ready) return <Loading />
  return <main className="internal-login-page"><div className="internal-login-brand"><span className="brand-mark">♻</span><span>DWMP <small>{workspace === 'admin' ? 'ADMIN SOFTWARE' : 'MANAGEMENT SOFTWARE'}</small></span></div><section className="internal-login-card"><p className="eyebrow">Private {workspace === 'admin' ? 'administrator' : 'management'} software</p><h1>{workspace === 'admin' ? 'Admin sign in' : 'Management sign in'}</h1><p className="muted">This workspace is for authorized {workspace === 'admin' ? 'system administrators' : 'operations staff'}.</p><form className="form-stack" onSubmit={submit}><Field label="Work email" name="email" type="email" autoComplete="username" required/><PasswordField label="Password" name="password" autoComplete="current-password" minLength={1} required/>{error&&<p className="form-error" role="alert">{error}</p>}<button className="button button-full" disabled={busy}>{busy?'Verifying…':'Sign in'}</button></form><p className="internal-security-note">Access is logged and limited to your assigned role.</p></section><footer>Digital Waste Management Platform · Internal use</footer></main>
}

function PublicLayout({ user }: { user: User | null }) {
  const resident = user?.role === 'citizen'
  return <><header className="public-header"><Link className="brand" to="/"><span className="brand-mark">♻</span><span>Digital Waste<br />Management Platform</span></Link><nav><NavLink to="/">Home</NavLink><NavLink to="/services">Services</NavLink><NavLink to="/service-updates">Service updates</NavLink></nav><div className="header-actions">{resident ? <Link className="button button-small" to="/dashboard">My account</Link> : <><Link className="sign-in" to="/login">Sign in</Link><Link className="button button-small" to="/register">Register</Link></>}</div></header><main><Outlet /></main><footer className="public-footer"><span>Digital Waste Management Platform</span><span>Waste services made easier for your community.</span></footer></>
}

function Home() {
  return <><section className="hero"><div className="hero-copy"><p className="eyebrow">A cleaner community starts here</p><h1>Manage your waste services easily</h1><p>Pay waste fees and report collection problems in a few simple steps.</p><div className="hero-actions"><Link className="button" to="/register">Create an account</Link><Link className="button button-outline" to="/services">Explore services</Link></div></div><div className="hero-art" aria-hidden="true"><div className="sun"/><div className="hill hill-back"/><div className="hill hill-front"/><div className="bin"><div className="bin-lid"/><div className="bin-body"><span>♻</span></div><div className="bin-wheel left"/><div className="bin-wheel right"/></div><div className="leaf leaf-one">✦</div><div className="leaf leaf-two">✦</div><div className="art-label"><span className="status-dot"/> A cleaner tomorrow</div></div></section><section className="section service-intro"><div><p className="eyebrow">How we can help</p><h2>Everyday services, all in one place</h2></div><div className="service-cards"><ServiceCard number="01" title="Manage waste fees" text="Review your service fees and keep payment records in one place." to="/dashboard/payments" /><ServiceCard number="02" title="Report a problem" text="Tell us about missed pickups, overflowing skips, or illegal dumping." to="/dashboard/complaints/new" /><ServiceCard number="03" title="Follow progress" text="Check updates on the issues you have reported." to="/login" /></div></section></>
}

function ServiceCard({ number, title, text, to }: { number: string; title: string; text: string; to: string }) { return <Link className="service-card" to={to}><span className="card-number">{number}</span><span className="card-title">{title}</span><span className="card-text">{text}</span><span className="card-arrow">↗</span></Link> }

function Services() { return <section className="page-wrap"><p className="eyebrow">Services</p><h1>Waste services for residents</h1><p className="page-lead">Use your account to manage payments, report a service problem, and track updates.</p><div className="service-cards services-grid"><ServiceCard number="01" title="Waste fees" text="Review payment information and access your payment records." to="/dashboard/payments"/><ServiceCard number="02" title="Report an issue" text="Submit a report and follow its status." to="/dashboard/complaints/new"/><ServiceCard number="03" title="Service updates" text="Read service notices published by authorized staff." to="/service-updates"/></div></section> }
function Updates() { const[data,setData]=useState<Awaited<ReturnType<typeof api.announcements>>['announcements']>([]);const[error,setError]=useState('');useEffect(()=>{api.announcements().then(x=>setData(x.announcements)).catch(e=>setError(e.message))},[]);return <section className="page-wrap"><p className="eyebrow">Service updates</p><h1>Updates for your area</h1><p className="page-lead">Notices published by authorized service staff.</p>{error&&<OperationError message={error}/>}<div className="public-updates">{data.length===0?<div className="empty-panel"><span className="empty-icon">◷</span><h2>No published updates yet</h2><p>When service notices are published, they will appear here.</p></div>:data.map(x=><article className="public-update" key={x.id}><p className="eyebrow">Service notice · {new Date(x.published_at||x.created_at).toLocaleDateString()}</p><h2>{x.title}</h2><p>{x.body}</p></article>)}</div></section> }

function AuthPage({ mode, saveUser }: { mode: 'login' | 'register'; saveUser: (u: User) => void }) {
  const navigate = useNavigate()
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setError('')
    const data = new FormData(event.currentTarget)
    const password = String(data.get('password'))
    if (mode === 'register' && password !== String(data.get('password_confirmation'))) {
      setError('The passwords do not match.')
      return
    }
    setBusy(true)
    try {
      const result = mode === 'login'
        ? await api.login(String(data.get('email')), password)
        : await api.register({ full_name: String(data.get('full_name')), email: String(data.get('email')), phone: String(data.get('phone')), password, terms_accepted: data.get('terms') === 'on' })
      if (result.user.role !== 'citizen') {
        setError('This page is for resident accounts.')
        return
      }
      saveUser(result.user)
      navigate('/dashboard')
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Please try again.')
    } finally {
      setBusy(false)
    }
  }
  return <section className="auth-wrap"><div className="auth-aside"><p className="eyebrow light">Resident services</p><h1>{mode === 'login' ? 'Welcome back.' : 'A simpler way to manage services.'}</h1><p>Manage your waste services and keep track of the things you report.</p><span className="auth-aside-mark">♻</span></div><div className="auth-card"><p className="eyebrow">{mode === 'login' ? 'Your account' : 'Get started'}</p><h2>{mode === 'login' ? 'Sign in' : 'Create your account'}</h2><p className="muted">{mode === 'login' ? 'Use your email and password to continue.' : 'Enter your details to register for resident services.'}</p><form onSubmit={submit} className="form-stack">{mode === 'register' && <><Field label="Full name" name="full_name" autoComplete="name" required/><Field label="Phone number" name="phone" type="tel" autoComplete="tel" required/></>}<Field label="Email address" name="email" type="email" autoComplete="email" required/><PasswordField label="Password" name="password" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} minLength={mode === 'register' ? 12 : 1} required/>{mode === 'register' && <PasswordField label="Confirm password" name="password_confirmation" autoComplete="new-password" minLength={12} required/>}{mode === 'register' && <label className="check-field"><input type="checkbox" name="terms" required/><span>I accept the applicable terms of service.</span></label>}{error && <p className="form-error" role="alert">{error}</p>}<button className="button button-full" disabled={busy}>{busy ? 'Please wait…' : mode === 'login' ? 'Sign in' : 'Create account'}</button></form>{mode === 'login' ? <><p className="auth-switch"><Link to="/forgot-password">Forgot your password?</Link></p><p className="auth-switch">New here? <Link to="/register">Create an account</Link></p></> : <p className="auth-switch">Already registered? <Link to="/login">Sign in</Link></p>}</div></section>
}

function ForgotPassword(){const[message,setMessage]=useState('');const[token,setToken]=useState('');const[error,setError]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setMessage('');setError('');const d=new FormData(e.currentTarget);try{const result=await api.forgotPassword(String(d.get('email')));setMessage(result.message);setToken(result.development_token||'')}catch(e){setError(e instanceof Error?e.message:'Recovery request failed')}}return <section className="auth-wrap"><div className="auth-aside"><p className="eyebrow light">Account recovery</p><h1>Let’s get you back in.</h1><p>Request a secure password reset for your resident account.</p></div><div className="auth-card"><p className="eyebrow">Account help</p><h2>Forgot password?</h2><p className="muted">Enter the email on your account to request a reset.</p><form className="form-stack" onSubmit={submit}><Field label="Email address" name="email" type="email" autoComplete="email" required/>{error&&<p className="form-error" role="alert">{error}</p>}{message&&<div className="success-message">{message}</div>}{token&&<div className="secret-panel"><strong>Local development reset token</strong><code>{token}</code><Link className="text-link" to={`/reset-password?token=${encodeURIComponent(token)}`}>Continue to password reset →</Link></div>}<button className="button">Request reset</button></form><p className="auth-switch"><Link to="/login">Back to sign in</Link></p></div></section>}

function ResetPassword(){const[token,setToken]=useState(new URLSearchParams(location.search).get('token')||'');const[message,setMessage]=useState('');const[error,setError]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);try{const result=await api.resetPassword(token,String(d.get('password')));setMessage(result.message);setError('')}catch(e){setError(e instanceof Error?e.message:'Password reset failed')}}return <section className="auth-wrap"><div className="auth-aside"><p className="eyebrow light">Account recovery</p><h1>Choose a new password.</h1><p>Recovery tokens expire after 30 minutes and can only be used once.</p></div><div className="auth-card"><p className="eyebrow">Secure your account</p><h2>Reset password</h2><form className="form-stack" onSubmit={submit}><label className="field"><span>Recovery token</span><input value={token} onChange={e=>setToken(e.target.value)} required/></label><PasswordField label="New password" name="password" autoComplete="new-password" minLength={12} required/>{error&&<p className="form-error" role="alert">{error}</p>}{message&&<div className="success-message">{message} <Link to="/login">Sign in</Link></div>}<button className="button">Set new password</button></form></div></section>}

function Field({ label,name,type='text',autoComplete,required=true,defaultValue,placeholder }: {label:string;name:string;type?:string;autoComplete?:string;required?:boolean;defaultValue?:string;placeholder?:string}) { return <label className="field"><span>{label}</span><input name={name} type={type} autoComplete={autoComplete} required={required} defaultValue={defaultValue} placeholder={placeholder}/></label> }
function PasswordField({ label,name,autoComplete,minLength,required }: {label:string;name:string;autoComplete:string;minLength:number;required:boolean}) { const [visible,setVisible]=useState(false);return <label className="field"><span>{label}</span><span className="password-wrap"><input name={name} type={visible?'text':'password'} autoComplete={autoComplete} minLength={minLength} required={required}/><button type="button" onClick={()=>setVisible(!visible)} aria-label={visible?'Hide password':'Show password'}>{visible?'Hide':'Show'}</button></span></label> }

function CitizenLayout({ user,signOut }: {user:User|null;signOut:()=>void}) { return <div className="citizen-shell"><aside className="citizen-sidebar"><Link className="brand sidebar-brand" to="/dashboard"><span className="brand-mark">♻</span><span>DWMP<br/><small>Resident portal</small></span></Link><p className="nav-caption">YOUR SERVICES</p><nav className="side-nav"><SideLink to="/dashboard" end icon="⌂">Overview</SideLink><SideLink to="/dashboard/complaints" icon="▤">My complaints</SideLink><SideLink to="/dashboard/payments" icon="₦">Payments</SideLink><SideLink to="/dashboard/profile" icon="○">My profile</SideLink></nav><div className="sidebar-help"><strong>Need help?</strong><span>Use the complaint form to report a collection problem.</span><Link to="/dashboard/complaints/new">Report an issue →</Link></div><button className="logout-button" onClick={signOut}>↪ <span>Sign out</span></button></aside><div className="citizen-main"><header className="citizen-topbar"><div><span className="muted">Resident account</span><strong>{user?.full_name}</strong></div><span className="avatar">{user?.full_name.slice(0,1).toUpperCase()}</span></header><main className="citizen-content"><Outlet /></main></div></div> }
function SideLink({to,icon,children,end=false}:{to:string;icon:string;children:ReactNode;end?:boolean}) {return <NavLink to={to} end={end} className={({isActive})=>`side-link${isActive?' active':''}`}><span className="side-icon">{icon}</span>{children}</NavLink>}

function ResidentBinActivity(){
  const [properties,setProperties]=useState<Awaited<ReturnType<typeof api.properties>>['properties']>([])
  const [error,setError]=useState('')
  useEffect(()=>{
    let active=true
    const refresh=()=>{if(document.visibilityState==='visible')api.properties().then(result=>{if(active){setProperties(result.properties);setError('')}}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Bin activity could not be loaded')})}
    refresh()
    const timer=window.setInterval(refresh,30000)
    document.addEventListener('visibilitychange',refresh)
    return()=>{active=false;window.clearInterval(timer);document.removeEventListener('visibilitychange',refresh)}
  },[])
  const bins=properties.flatMap(property=>property.bins.map(bin=>({property,bin}))).sort((a,b)=>new Date(b.bin.last_evacuated_at||0).getTime()-new Date(a.bin.last_evacuated_at||0).getTime()).slice(0,5)
  return <section className="panel"><div className="panel-heading"><div><h2>Bin collection activity</h2><p>Latest evacuation updates for your five most recently collected bins.</p></div><Link className="text-link" to="/dashboard/profile">View all bins and history</Link></div>{error?<p className="form-error" role="alert">{error}</p>:bins.length===0?<p className="empty-inline">No registered bins are linked to your account yet.</p>:<div className="table-wrap"><table><thead><tr><th>Bin ID</th><th>Address</th><th>Unit</th><th>Last evacuation</th><th>Recorded by</th></tr></thead><tbody>{bins.map(({property,bin})=><tr key={bin.id}><td><strong>{bin.tracking_id}</strong></td><td>{property.address}</td><td>{bin.unit_code||'Shared property'}</td><td>{bin.last_evacuated_at?new Date(bin.last_evacuated_at).toLocaleString():'No evacuation recorded yet'}<BinEvacuationHistory binID={bin.id}/></td><td>{bin.evacuated_by||'—'}</td></tr>)}</tbody></table></div>}</section>
}

function CitizenHome(){const[user,setUser]=useState<User|null>(null);const[items,setItems]=useState<Complaint[]>([]);const[payments,setPayments]=useState<Awaited<ReturnType<typeof api.payments>>['payments']>([]);const[updates,setUpdates]=useState<Awaited<ReturnType<typeof api.announcements>>['announcements']>([]);const[fee,setFee]=useState<number|null>(null);const[error,setError]=useState('');useEffect(()=>{api.me().then(x=>setUser(x.user)).catch(e=>setError(e.message));api.complaints().then(x=>setItems(x.complaints)).catch(e=>setError(e.message));api.payments().then(x=>setPayments(x.payments)).catch(e=>setError(e.message));api.announcements().then(x=>setUpdates(x.announcements)).catch(e=>setError(e.message));api.locations().then(x=>x.locations[0]?api.paymentOptions(String(x.locations[0].id)).then(o=>setFee(o.fee_amount_kobo)):setFee(null)).catch(()=>setFee(null))},[]);const open=items.filter(x=>!['resolved','rejected'].includes(x.status)).length;return <><div className="content-heading"><div><p className="eyebrow">Your account</p><h1>Hello, {user?.full_name.split(' ')[0]||'there'}</h1><p className="muted">Here is an overview of your service activity.</p></div><Link to="/dashboard/complaints/new" className="button">＋ Report an issue</Link></div><div className="welcome-strip"><div><span className="strip-kicker">RESIDENT SERVICES</span><h2>Keep your services moving.</h2><p>Report a problem and follow its progress from your account.</p></div><span className="strip-art" aria-hidden="true">♻</span></div>{error&&<OperationError message={error}/>}<div className="stat-grid"><Stat label="Open complaints" value={String(open)} icon="▤"/><Stat label="Configured waste fee" value={fee&&fee>0?formatNaira(fee):'Not set'} icon="₦" note="Based on your first saved property area"/><Stat label="Recent payments" value={String(payments.length)} icon="▣" note={`${updates.length} published service updates`} /></div><ResidentBinActivity/><section className="panel"><div className="panel-heading"><div><h2>Recent complaints</h2><p>Updates on reports you have submitted.</p></div><Link className="text-link" to="/dashboard/complaints">View all →</Link></div>{items.length===0?<div className="empty-inline"><span>Nothing to show yet.</span><Link to="/dashboard/complaints/new">Submit your first report</Link></div>:<ComplaintTable items={items.slice(0,5)}/>}</section><section className="panel"><div className="panel-heading"><div><h2>Recent payments</h2><p>Payment receipts are available for completed records.</p></div><Link className="text-link" to="/dashboard/payments">View payments →</Link></div>{payments.length===0?<div className="empty-inline">No payment records yet.</div>:<div className="table-wrap"><table><thead><tr><th>Reference</th><th>Property</th><th>Date</th><th>Amount</th><th>Status</th><th>Receipt</th></tr></thead><tbody>{payments.slice(0,4).map(p=><tr key={p.reference}><td>{p.reference}</td><td>{p.location_label||'Legacy payment'}</td><td>{new Date(p.created_at).toLocaleDateString()}</td><td>{formatNaira(p.amount_kobo)}</td><td><Status value={p.mode==='simulation'&&p.status==='succeeded'?'simulated_success':p.status}/></td><td>{p.receipt_reference?<Link className="reference-link" to={`/receipts/${p.receipt_reference}`}>View receipt</Link>:'—'}</td></tr>)}</tbody></table></div>}</section><section className="panel"><div className="panel-heading"><div><h2>Service updates</h2><p>Published notices from service staff.</p></div><Link className="text-link" to="/service-updates">View all →</Link></div>{updates.length===0?<div className="empty-inline">No published service updates yet.</div>:updates.slice(0,2).map(item=><article className="announcement-row" key={item.id}><p className="eyebrow">{new Date(item.published_at||item.created_at).toLocaleDateString()}</p><h3>{item.title}</h3><p>{item.body}</p></article>)}</section></>}
function Stat({label,value,icon,note}:{label:string;value:string;icon:string;note?:string}){return <div className="stat-card"><span className="stat-icon">{icon}</span><span className="stat-label">{label}</span><strong>{value}</strong>{note&&<small>{note}</small>}</div>}

function ComplaintList(){const[items,setItems]=useState<Complaint[]>([]);const[error,setError]=useState('');const[loading,setLoading]=useState(true);useEffect(()=>{api.complaints().then(x=>setItems(x.complaints)).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[]);return <><div className="content-heading"><div><p className="eyebrow">Resident services</p><h1>My complaints</h1><p className="muted">Check the status of the service issues you have reported.</p></div><Link to="/dashboard/complaints/new" className="button">＋ New complaint</Link></div><section className="panel">{loading?<Loading/>:error?<p className="form-error">{error}</p>:items.length===0?<div className="empty-panel"><span className="empty-icon">▤</span><h2>No complaints yet</h2><p>Reports you submit will appear here.</p><Link to="/dashboard/complaints/new" className="button">Report an issue</Link></div>:<ComplaintTable items={items}/>}</section></>}
function ComplaintTable({items}:{items:Complaint[]}){return <div className="table-wrap"><table><thead><tr><th>Reference</th><th>Issue</th><th>Location</th><th>Status</th><th>Submitted</th><th></th></tr></thead><tbody>{items.map(item=><tr key={item.reference}><td><Link className="reference-link" to={`/dashboard/complaints/${item.reference}`}>{item.reference}</Link></td><td>{categoryLabel(item.category)}</td><td>{item.location}</td><td><Status value={item.status}/></td><td>{new Date(item.created_at).toLocaleDateString()}</td><td><Link className="row-link" to={`/dashboard/complaints/${item.reference}`}>View →</Link></td></tr>)}</tbody></table></div>}
function ComplaintForm(){const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[reference,setReference]=useState('');const[locations,setLocations]=useState<ResidentLocation[]>([]);useEffect(()=>{api.locations().then(x=>setLocations(x.locations)).catch(e=>setError(e.message))},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setError('');setBusy(true);const d=new FormData(e.currentTarget);try{const r=await api.createComplaint({category:String(d.get('category')),description:String(d.get('description')),location_id:Number(d.get('location_id'))});setReference(r.complaint.reference)}catch(e){setError(e instanceof Error?e.message:'Could not submit the report.')}finally{setBusy(false)}}if(reference)return <section className="success-card"><span className="success-mark">✓</span><p className="eyebrow">Report received</p><h1>Your complaint is submitted.</h1><p>Keep this reference for your records: <strong>{reference}</strong></p><p>You can follow its status from your account.</p><Link className="button" to={`/dashboard/complaints/${reference}`}>View complaint</Link></section>;return <><div className="content-heading"><div><p className="eyebrow">Resident services</p><h1>Report a problem</h1><p className="muted">Share a few details so the team can review the issue.</p></div></div><section className="panel form-panel"><form className="form-stack" onSubmit={submit}><label className="field"><span>Issue type</span><select name="category" required defaultValue=""><option value="" disabled>Select an issue</option><option value="overflowing_skip">Overflowing waste skip</option><option value="missed_collection">Missed waste collection</option><option value="illegal_dumping">Illegal dumping</option><option value="other">Other sanitation issue</option></select></label><label className="field"><span>Where is the waste service registered?</span><select name="location_id" required defaultValue=""><option value="" disabled>{locations.length?'Choose a home, shop, or other saved place':'Add a service address in Profile first'}</option>{locations.map(x=><option value={x.id} key={x.id}>{x.label} — {x.address_line1}, {x.locality}</option>)}</select></label><label className="field"><span>Description</span><textarea name="description" minLength={10} maxLength={4000} rows={5} required placeholder="Describe what happened and when you noticed it."/></label><p className="muted form-hint">The selected address will be included with the report so the service team can locate the property.</p>{error&&<p className="form-error" role="alert">{error}</p>}{locations.length===0&&<Link className="text-link" to="/dashboard/profile">Add a home or business address →</Link>}<button className="button" disabled={busy||locations.length===0}>{busy?'Submitting…':'Submit complaint'}</button></form></section></>}
function ComplaintDetails(){const{reference=''}=useParams();const[data,setData]=useState<Awaited<ReturnType<typeof api.complaint>>|null>(null);const[error,setError]=useState('');useEffect(()=>{api.complaint(reference).then(setData).catch(e=>setError(e.message))},[reference]);if(error)return <div className="panel"><p className="form-error">{error}</p><Link to="/dashboard/complaints">Back to complaints</Link></div>;if(!data)return <Loading/>;return <><div className="content-heading"><div><p className="eyebrow">Complaint {data.complaint.reference}</p><h1>{categoryLabel(data.complaint.category)}</h1><p className="muted">Submitted {new Date(data.complaint.created_at).toLocaleString()}</p></div><Status value={data.complaint.status}/></div><div className="detail-grid"><section className="panel"><h2>Report details</h2><dl className="detail-list"><dt>Location</dt><dd>{data.complaint.location}</dd><dt>Description</dt><dd>{data.complaint.description}</dd></dl></section><section className="panel"><h2>Status history</h2><ol className="timeline">{data.history.map((step,i)=><li key={`${step.created_at}-${i}`}><span className="timeline-dot"/><strong>{statusLabel(step.status)}</strong><p>{step.note}</p><small>{new Date(step.created_at).toLocaleString()}</small></li>)}</ol></section></div></>}
function Payments(){
  const [options,setOptions]=useState<Awaited<ReturnType<typeof api.paymentOptions>>|null>(null)
  const [items,setItems]=useState<Awaited<ReturnType<typeof api.payments>>['payments']>([])
  const [invoices,setInvoices]=useState<Awaited<ReturnType<typeof api.monthlyInvoices>>['invoices']>([])
  const [locations,setLocations]=useState<ResidentLocation[]>([])
  const [locationId,setLocationId]=useState('')
  const [error,setError]=useState('')
  const load=(selectedLocation=locationId)=>Promise.all([api.paymentOptions(selectedLocation),api.payments(),api.monthlyInvoices(selectedLocation)]).then(([o,p,b])=>{setOptions(o);setItems(p.payments);setInvoices(b.invoices)}).catch(e=>setError(e.message))
  useEffect(()=>{api.locations().then(x=>{setLocations(x.locations);if(x.locations[0])setLocationId(String(x.locations[0].id));else load('')}).catch(e=>setError(e.message))},[])
  useEffect(()=>{if(locationId)load(locationId)},[locationId])
  return <><div className="content-heading"><div><p className="eyebrow">Resident services</p><h1>Payments</h1><p className="muted">Monthly service bills are issued for each active service address and are due by the 7th.</p></div></div><OperationError message={error}/><div className="notice-panel"><span className="notice-icon">NGN</span><div><h2>{options?.area_name?`Waste service fee: ${options.area_name}`:'Area waste service fee'}</h2>{options?.fee_breakdown?<><p>{options.fee_breakdown.delivered_bins.length>0&&<>Your area's 60 L base fee is {formatNaira(options.fee_breakdown.base_bin_fee_kobo||0)}. Each delivered bin assigned to you is priced in proportion to its capacity; for example, a 120 L bin costs twice the base. Your total is the sum of your assigned bin prices, with no extra area fee.<br/></>}{options.fee_breakdown.area_flat_fee_kobo>0&&<>60 L base fee: {formatNaira(options.fee_breakdown.area_flat_fee_kobo)}<br/></>}{options.fee_breakdown.delivered_bins.length>0&&<>Your assigned bins ({options.fee_breakdown.delivered_bins.length}): {formatNaira(options.fee_breakdown.bin_size_fee_kobo)}<br/></>}<strong>Total: {formatNaira(options.fee_amount_kobo)}</strong></p>{options.fee_breakdown.delivered_bins.length>0&&<ul>{options.fee_breakdown.delivered_bins.map(bin=><li key={bin.bin_id}>Bin {bin.bin_id} ({bin.size_litres} L): {formatNaira(bin.amount_kobo)}</li>)}</ul>}</>:<p>{options?.message||'Choose a saved address to see the fee for its area.'}</p>}<label className="field"><span>Service address</span><select value={locationId} onChange={e=>setLocationId(e.target.value)}><option value="">Choose a saved address</option>{locations.map(x=><option key={x.id} value={x.id}>{x.label} - {x.address_line1}, {x.locality}, {x.city}, {x.state}</option>)}</select></label>{locations.length===0&&<Link className="text-link" to="/dashboard/profile">Add a home or business address</Link>}<button className="button" type="button" disabled aria-describedby="payment-placeholder-note">Pay now</button><p id="payment-placeholder-note" className="muted">Payment is not connected yet. No payment will be started.</p></div></div><section className="panel"><div className="panel-heading"><div><h2>Monthly bills</h2><p>Each bill is based on the delivered bins assigned to this address. Unpaid bills remain outstanding.</p></div><strong>Outstanding: {formatNaira(invoices.filter(x=>x.status==='due'||x.status==='overdue').reduce((total,x)=>total+x.amount_kobo,0))}</strong></div>{invoices.length===0?<div className="empty-inline">No monthly bills have been issued for this address yet.</div>:<div className="table-wrap"><table><thead><tr><th>Billing month</th><th>Due date</th><th>Amount</th><th>Status</th><th>Bill reference</th></tr></thead><tbody>{invoices.map(invoice=><tr key={invoice.reference}><td>{new Date(`${invoice.billing_month}T00:00:00`).toLocaleDateString(undefined,{month:'long',year:'numeric'})}</td><td>{new Date(`${invoice.due_date}T00:00:00`).toLocaleDateString()}</td><td>{formatNaira(invoice.amount_kobo)}</td><td><Status value={invoice.status}/></td><td>{invoice.reference}</td></tr>)}</tbody></table></div>}</section><section className="panel"><div className="panel-heading"><div><h2>Payment records</h2><p>Online payments are not available yet. Existing records, if any, are shown below.</p></div></div>{items.length===0?<div className="empty-inline">No payment records yet.</div>:<div className="table-wrap"><table><thead><tr><th>Reference</th><th>Property</th><th>Date</th><th>Amount</th><th>Status</th><th>Mode</th><th>Next step</th></tr></thead><tbody>{items.map(p=><tr key={p.reference}><td>{p.reference}</td><td>{p.location_label||'Legacy payment'}</td><td>{new Date(p.created_at).toLocaleDateString()}</td><td>{formatNaira(p.amount_kobo)}</td><td><Status value={p.mode==='simulation'&&p.status==='succeeded'?'simulated_success':p.status}/></td><td>{p.mode==='simulation'?'Demonstration':'Provider'}</td><td>{p.receipt_reference?<Link className="reference-link" to={`/receipts/${p.receipt_reference}`}>View receipt</Link>:p.status==='pending'?'Payment unavailable':'-'}</td></tr>)}</tbody></table></div>}</section></>
}

function ReceiptView(){const{reference=''}=useParams();const[receipt,setReceipt]=useState<Awaited<ReturnType<typeof api.receipt>>['receipt']|null>(null);const[error,setError]=useState('');useEffect(()=>{api.receipt(reference).then(x=>setReceipt(x.receipt)).catch(e=>setError(e.message))},[reference]);if(error)return <section className="page-wrap"><OperationError message={error}/><Link to="/dashboard/payments">Back to payments</Link></section>;if(!receipt)return <Loading/>;return <section className="page-wrap receipt-page"><div className="receipt-top"><span className="brand-mark">♻</span><span>{receipt.simulated?'DEMONSTRATION RECEIPT':'PAYMENT RECEIPT'}</span></div><p className="eyebrow">Receipt {receipt.reference}</p><h1>Payment record</h1><div className="receipt-amount">{formatNaira(receipt.amount_kobo)}</div><dl className="detail-list"><dt>Payment reference</dt><dd>{receipt.payment_reference}</dd><dt>Service</dt><dd>Waste service fee</dd><dt>Status</dt><dd><Status value={receipt.simulated?'simulated_success':receipt.status}/></dd><dt>Recorded</dt><dd>{new Date(receipt.created_at).toLocaleString()}</dd></dl>{receipt.simulated&&<p className="form-hint">Demonstration record only. No money was collected or transferred.</p>}<Link className="button" to="/dashboard/payments">Back to payments</Link></section>}

function formatNaira(kobo:number){return new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN'}).format(kobo/100)}
function Profile({user,saveUser}:{user:User|null;saveUser:(u:User)=>void}){const[error,setError]=useState('');const[message,setMessage]=useState('');const[busy,setBusy]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);setError('');setMessage('');setBusy(true);try{const result=await api.updateProfile({full_name:String(d.get('full_name')),phone:String(d.get('phone'))});saveUser(result.user);setMessage('Profile updated.')}catch(e){setError(e instanceof Error?e.message:'Profile could not be updated')}finally{setBusy(false)}}return <><div className="content-heading"><div><p className="eyebrow">Your account</p><h1>Profile</h1><p className="muted">Update your name and contact number.</p></div></div><section className="panel form-panel"><form className="form-stack" onSubmit={submit}><Field label="Full name" name="full_name" autoComplete="name" required defaultValue={user?.full_name}/><label className="field"><span>Email address</span><input type="email" value={user?.email||''} readOnly/></label><Field label="Phone number" name="phone" type="tel" autoComplete="tel" required defaultValue={user?.phone}/>{message&&<p className="success-message">{message}</p>}{error&&<OperationError message={error}/>}<button className="button" disabled={busy}>{busy?'Saving…':'Save profile'}</button></form></section><ManagedLocationsPanel/><PropertyRegistrationPanel/></>}

function StaffLayout({user,signOut,type}:{user:User|null;signOut:()=>void;type:'operations'|'admin'}) {const currentPath=useLocation().pathname;const isOps=type==='operations';const base=isOps?'/operations':'/admin';const links=isOps?['Overview','Complaints','Payments','Property applications','Containers','Collections','Inspections','Alerts','Analytics','Announcements']:['Overview','Staff & roles','Devices','Organization activity','Settings','Audit logs'];return <div className="staff-shell"><aside className="staff-sidebar"><Link to={base} className="brand sidebar-brand"><span className="brand-mark">♻</span><span>DWMP<br/><small>{isOps?'Operations':'Administration'}</small></span></Link><p className="nav-caption">WORKSPACE</p><nav className="side-nav">{links.map((label,i)=><NavLink key={label} to={i===0?base:`${base}/${label.toLowerCase().replaceAll(' ','-')}`} end={i===0} className={({isActive})=>`side-link${isActive?' active':''}`}><span className="side-icon">{['⌂','▤','▦','▣','◉','⚑','◷','▧'][i]}</span>{label}</NavLink>)}</nav><button className="logout-button" onClick={signOut}>↪ <span>Sign out</span></button></aside><div className="staff-main"><header className="staff-topbar"><div><span className="workspace-tag">{isOps?'OPERATIONS':'SYSTEM ADMINISTRATION'}</span><strong>{user?.full_name}</strong></div><span className="avatar">{user?.full_name.slice(0,1).toUpperCase()}</span></header><main className="staff-content"><Routes><Route index element={<StaffOverview type={type}/>} /><Route path="*" element={<StaffSection label={decodeURIComponent(currentPath.split('/').pop()||'Workspace').replaceAll('-',' ')} type={type}/>} /></Routes></main></div></div>}
function StaffOverview({type}:{type:'operations'|'admin'}){
  const ops=type==='operations'
  const [metrics,setMetrics]=useState<{label:string;value:string;icon:string;note?:string}[]>([])
  const [error,setError]=useState('')
  useEffect(()=>{
    if(ops){
      api.analytics().then(x=>setMetrics([
        {label:'Active complaints',value:String(x.active_complaints),icon:'▤'},
        {label:'Registered containers',value:String(x.registered_containers),icon:'▦'},
        {label:'Offline devices',value:String(x.offline_devices),icon:'◉'},
        {label:'Overdue collections',value:String(x.overdue_collections),icon:'◷'},
        {label:'Collections completed',value:String(x.completed_collections_30d),icon:'✓',note:'Last 30 days'},
      ])).catch(e=>setError(e.message))
    }else{
      Promise.all([api.staff(),api.devices(),api.areaFees(),api.auditLogs()]).then(([staff,devices,fees,audit])=>setMetrics([
        {label:'Active staff',value:String(staff.staff.filter(x=>x.active).length),icon:'▤'},
        {label:'Registered devices',value:String(devices.devices.length),icon:'▦'},
        {label:'Configured fee areas',value:String(fees.area_fees.length),icon:'₦'},
        {label:'Audit events',value:String(audit.audit_logs.length),icon:'◉',note:'Most recent 200'},
      ])).catch(e=>setError(e.message))
    }
  },[ops])
  return <><div className="content-heading"><div><p className="eyebrow">{ops?'Operational overview':'System overview'}</p><h1>{ops?'Operations dashboard':'Administration'}</h1><p className="muted">{ops?'Live service activity from the operations API.':'Live staff, resident, device, fee, and audit activity from the admin API.'}</p></div></div><OperationError message={error}/><div className="stat-grid">{metrics.map(x=><Stat key={x.label} {...x}/>)}</div><p className="dashboard-hint">Choose a workspace section from the navigation to review or manage its records.</p></>
}

function BinQrLabel({trackingId}:{trackingId:string}) {
  const [image,setImage]=useState('')
  const [error,setError]=useState('')
  useEffect(()=>{let active=true;QRCode.toDataURL(trackingId,{errorCorrectionLevel:'M',margin:2,width:240}).then(qr=>{const codeImage=new Image();codeImage.onload=()=>{if(!active)return;const canvas=document.createElement('canvas');canvas.width=360;canvas.height=320;const context=canvas.getContext('2d');if(!context){setError('QR label could not be rendered');return}context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(codeImage,60,12,240,240);context.fillStyle='#17211b';context.font='bold 20px Arial';context.textAlign='center';context.fillText(trackingId,180,292);setImage(canvas.toDataURL('image/png'));setError('')};codeImage.onerror=()=>{if(active)setError('QR label could not be rendered')};codeImage.src=qr}).catch(()=>{if(active)setError('QR code could not be created')});return()=>{active=false}},[trackingId])
  return <details className="bin-qr-details"><summary>View or download bin label</summary><div className="bin-qr-label">{image?<img src={image} alt={`Printable QR label for bin ${trackingId}`}/>:<span>{error||'Creating QR code…'}</span>}<div><strong>{trackingId}</strong><a className="button button-small button-outline" href={image||undefined} download={`${trackingId}-label.png`} aria-disabled={!image}>Download label</a></div></div></details>
}

function BinQrScanner({onScan}:{onScan:(trackingId:string)=>void}) {
  const videoRef=useRef<HTMLVideoElement>(null)
  const [active,setActive]=useState(false)
  const [message,setMessage]=useState('')
  useEffect(()=>{
    if(!active||!videoRef.current)return
    let stopped=false
    let controls:IScannerControls|undefined
    const reader=new BrowserQRCodeReader()
    reader.decodeFromVideoDevice(undefined,videoRef.current,(result,_error,scanControls)=>{
      controls=scanControls
      if(!result||stopped)return
      const value=result.getText().trim().toUpperCase()
      if(!/^DWMP-[A-F0-9]{32}$/.test(value)){
        setMessage('This QR code is not a recognized DWMP bin ID. Aim at the bin label.')
        return
      }
      onScan(value)
      setMessage('Bin ID scanned. Confirm the evacuation when the bin has been collected.')
      setActive(false)
      scanControls.stop()
    }).then(scanControls=>{controls=scanControls;if(stopped)scanControls.stop()}).catch(()=>{
      if(!stopped){setMessage('Camera could not start. Allow camera access and use HTTPS, or enter the ID manually.');setActive(false)}
    })
    return()=>{stopped=true;controls?.stop()}
  },[active,onScan])
  return <div className="bin-scanner"><div className="button-row"><button className="button button-outline" type="button" onClick={()=>{setMessage('');setActive(value=>!value)}}>{active?'Stop camera':'Scan bin QR with camera'}</button>{message&&<span className="muted" role="status">{message}</span>}</div>{active&&<video ref={videoRef} className="bin-scanner-video" autoPlay muted playsInline aria-label="Live camera view for scanning the bin QR code"/>}</div>
}

function StaffSection({label,type}:{label:string;type:'operations'|'admin'}){
  const key=label.toLowerCase().replaceAll('-',' ').trim()
  if(type==='operations'){
    if(key==='complaints')return <OperationsComplaints/>
    if(key==='payments')return <OperationsPayments/>
    if(key==='containers')return <OperationsContainerConsole/>
    if(key==='property registrations'||key==='property applications')return <OperationsPropertyRegistrations/>
    if(key==='collections')return <OperationsCollections/>
    if(key==='inspections')return <OperationsInspections/>
    if(key==='analytics')return <OperationsAnalytics/>
    if(key==='alerts'||key==='notifications')return <OperationsAlerts/>
    if(key==='announcements')return <OperationsAnnouncements/>
  }else{
    if(key==='staff & roles')return <AdminStaff/>
    if(key==='devices')return <AdminDevicesConsole/>
    if(key==='organization activity')return <AdminActivityFeed/>
    if(key==='settings')return <><AdminSettings/><ManagedAreaFees/></>
    if(key==='audit logs')return <AdminAuditLogs/>
  }
  return <><div className="content-heading"><div><p className="eyebrow">{type==='operations'?'Operations':'Administration'}</p><h1>{label.replace(/^./,c=>c.toUpperCase())}</h1><p className="muted">This view will use live records from the shared service database.</p></div></div><div className="empty-panel panel"><span className="empty-icon">◷</span><h2>No workflow records are available</h2><p>There are no records to display for this area yet.</p></div></>
}

function OpsTitle({title,description,action}:{title:string;description:string;action?:ReactNode}){return <div className="content-heading"><div><p className="eyebrow">Operations workspace</p><h1>{title}</h1><p className="muted">{description}</p></div>{action}</div>}
function OperationError({message}:{message:string}){return message?<p className="form-error" role="alert">{message}</p>:null}

function OperationsPayments(){const[data,setData]=useState<Awaited<ReturnType<typeof api.operationsPayments>>['items']>([]);const[error,setError]=useState('');useEffect(()=>{api.operationsPayments().then(x=>setData(x.items)).catch(e=>setError(e.message))},[]);return <><OpsTitle title="Resident payments" description="View payment records and the property each payment covers."/><OperationError message={error}/><section className="panel"><div className="table-wrap"><table><thead><tr><th>Payment</th><th>Resident</th><th>Service address</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody>{data.map(x=><tr key={x.reference}><td>{x.reference}<br/><small>{x.mode==='simulation'?'Demonstration':'Provider'}</small></td><td>{x.resident.full_name}<br/><small>{x.resident.email} | {x.resident.phone}</small></td><td><strong>{x.location.label||'No address recorded'}</strong><br/><small>{x.location.address||'Legacy payment'}</small></td><td>{formatNaira(x.amount_kobo)}</td><td><Status value={x.status}/></td><td>{new Date(x.created_at).toLocaleString()}</td></tr>)}</tbody></table>{data.length===0&&<p className="empty-inline">No resident payment records.</p>}</div></section></>}

function OperationsPropertyRegistrations(){
  const [items,setItems]=useState<Awaited<ReturnType<typeof api.operationsProperties>>['properties']>([])
  const [requests,setRequests]=useState<Awaited<ReturnType<typeof api.operationsPropertyUnitRequests>>['requests']>([])
  const [areas,setAreas]=useState<Awaited<ReturnType<typeof api.operationsServiceAreas>>['service_areas']>([])
  const [createResidentAccount,setCreateResidentAccount]=useState(true)
  const [evacuationTrackingID,setEvacuationTrackingID]=useState('')
  const handleBinScan=useCallback((trackingId:string)=>setEvacuationTrackingID(trackingId),[])
  const [selected,setSelected]=useState<Awaited<ReturnType<typeof api.operationsPropertyDetails>>['property']|null>(null)
  const [page,setPage]=useState(1)
  const [total,setTotal]=useState(0)
  const [searchDraft,setSearchDraft]=useState('')
  const [search,setSearch]=useState('')
  const [statusFilter,setStatusFilter]=useState('')
  const [error,setError]=useState('')
  const [message,setMessage]=useState('')
  const [busy,setBusy]=useState(false)
  const [reasons,setReasons]=useState<Record<number,string>>({})
  const [applicationReasons,setApplicationReasons]=useState<Record<number,string>>({})
  const load=()=>Promise.all([api.operationsProperties(page,search,statusFilter),api.operationsPropertyUnitRequests(),api.operationsServiceAreas()]).then(([p,r,a])=>{setItems(p.properties);setTotal(p.total);setRequests(r.requests);setAreas(a.service_areas)}).catch(e=>setError(e.message))
  useEffect(()=>{load()},[page,search,statusFilter])
  async function openProperty(id:number){setBusy(true);setError('');try{const result=await api.operationsPropertyDetails(id);setSelected(result.property)}catch(e){setError(e instanceof Error?e.message:'Property details could not be loaded')}finally{setBusy(false)}}
  async function refreshSelected(id:number){await load();try{const result=await api.operationsPropertyDetails(id);setSelected(result.property)}catch(e){setError(e instanceof Error?e.message:'Property details could not be refreshed')}}
  async function handover(e:FormEvent<HTMLFormElement>,propertyId:number){e.preventDefault();const form=e.currentTarget;const d=new FormData(form);setBusy(true);setError('');setMessage('');try{const bin=await api.createPropertyBin(propertyId,{size_litres:Number(d.get('size_litres')),unit_id:d.get('unit_id')?Number(d.get('unit_id')):null,resident_email:String(d.get('resident_email')||'')});await api.recordBinDelivery(bin.id,{outcome:String(d.get('outcome')) as 'delivered'|'failed',note:String(d.get('note'))});setMessage(`Bin ${bin.tracking_id} registered. Its QR label is available in the bin profile below.`);form.reset();await refreshSelected(propertyId)}catch(e){setError(e instanceof Error?e.message:'Bin handover could not be recorded');await refreshSelected(propertyId)}finally{setBusy(false)}}
  async function recordEvacuation(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const d=new FormData(form);setBusy(true);setError('');setMessage('');try{const result=await api.recordBinEvacuation(String(d.get('tracking_id')),String(d.get('note')||''),String(d.get('resident_email')||''));setMessage(`Evacuation recorded for ${result.tracking_id}${result.unit_code?` · ${result.unit_code}`:''}. Resident: ${result.resident.full_name} (${result.resident.email}).`);form.reset();setEvacuationTrackingID('');await load()}catch(e){setError(e instanceof Error?e.message:'Bin evacuation could not be recorded')}finally{setBusy(false)}}
  async function reviewUnitRequest(id:number,decision:'approved'|'rejected'){const reason=(reasons[id]||'').trim();if(reason.length<5){setError('Enter a reason of at least 5 characters before deciding this request.');return}setBusy(true);setError('');setMessage('');try{await api.reviewPropertyUnitRequest(id,decision,reason);setReasons(prev=>({...prev,[id]:''}));await load();setMessage(`Unit request ${decision}. The resident can see the reason.`)}catch(e){setError(e instanceof Error?e.message:'Unit request could not be reviewed')}finally{setBusy(false)}}
  async function reviewApplication(id:number,decision:'approved'|'rejected'){const reason=(applicationReasons[id]||'').trim();if(reason.length<5){setError('Enter a reason of at least 5 characters before deciding this application.');return}setBusy(true);setError('');setMessage('');try{await api.reviewPropertyRegistration(id,decision,reason);setApplicationReasons(prev=>({...prev,[id]:''}));await refreshSelected(id);setMessage(decision==='approved'?'Application reviewed and accepted. Service will be verified after all bins are delivered.':'Application rejected. The resident can see the reason.')}catch(e){setError(e instanceof Error?e.message:'Property application could not be reviewed')}finally{setBusy(false)}}
  async function assistedRegistration(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const d=new FormData(form);const units=String(d.get('unit_codes')).split(',').map(entry=>entry.trim()).filter(Boolean).map(entry=>{const [code,...floor]=entry.split('|');return {code:code.trim(),floor_label:floor.join('|').trim(),unit_type:String(d.get('unit_type')),service_scope:String(d.get('service_scope'))}});setBusy(true);setError('');setMessage('');try{const result=await api.assistedPropertyRegistration({resident_email:String(d.get('resident_email')),create_account:createResidentAccount,resident_name:createResidentAccount?String(d.get('resident_name')):undefined,resident_phone:createResidentAccount?String(d.get('resident_phone')):undefined,password:createResidentAccount?String(d.get('password')):undefined,terms_accepted:createResidentAccount&&d.get('terms_accepted')==='on',area_id:Number(d.get('area_id')),label:String(d.get('label')),address_line1:String(d.get('address_line1')),address_line2:String(d.get('address_line2')),postal_code:String(d.get('postal_code')),property_type:String(d.get('property_type')),structure_type:String(d.get('structure_type')),floors:Number(d.get('floors')),registration_scope:String(d.get('registration_scope')),registrant_role:String(d.get('registrant_role')),units});form.reset();setCreateResidentAccount(true);await load();setMessage(result.account_created?'Resident account and assisted property registration created. The resident can now sign in using the email and password they entered.':'Assisted property registration saved to the existing resident account.')}catch(e){setError(e instanceof Error?e.message:'Assisted registration could not be saved')}finally{setBusy(false)}}
   const pageCount=Math.max(1,Math.ceil(total/25))
   return <><OpsTitle title="Property applications" description="Review applications from a searchable queue. Open one record at a time to see resident contact, address, units, and bin details."/><OperationError message={error}/>{message&&<p className="success-message">{message}</p>}<section className="panel"><h2>Record a bin evacuation</h2><p className="muted">Scan the printed bin tracking code with a scanner, or enter it here. The system records the collection against the bin's linked resident and unit.</p><form className="form-grid" onSubmit={recordEvacuation}><label className="field"><span>Scanned bin tracking ID</span><input name="tracking_id" autoComplete="off" minLength={4} maxLength={80} required value={evacuationTrackingID} onChange={e=>setEvacuationTrackingID(e.target.value.toUpperCase())}/><BinQrScanner onScan={handleBinScan}/></label><label className="field"><span>Resident email (only if this older bin needs account linking)</span><input name="resident_email" type="email" autoComplete="off"/></label><label className="field"><span>Collection note (optional)</span><input name="note" maxLength={500} placeholder="Optional note"/></label><button className="button" disabled={busy}>{busy?'Recording…':'Confirm evacuation'}</button></form></section>
    <details className="panel disclosure-panel"><summary>Assisted resident registration</summary><div className="disclosure-content"><p className="muted">Complete this with the resident. For a new account, let the resident enter their own password and confirm they accept the terms.</p><form className="form-grid" onSubmit={assistedRegistration}><label className="field"><span>Account setup</span><select value={createResidentAccount ? 'new' : 'existing'} onChange={e=>setCreateResidentAccount(e.target.value==='new')}><option value="new">Create a new resident account</option><option value="existing">Use an existing resident account</option></select></label>{createResidentAccount&&<><label className="field"><span>Resident full name</span><input name="resident_name" required minLength={2} maxLength={120}/></label><label className="field"><span>Resident phone</span><input name="resident_phone" type="tel" required minLength={7} maxLength={32}/></label></>}<label className="field"><span>Resident account email</span><input name="resident_email" type="email" required/></label>{createResidentAccount&&<><PasswordField label="Resident password (entered by resident)" name="password" autoComplete="new-password" minLength={12} required/><label className="field checkbox-field"><input name="terms_accepted" type="checkbox" required/><span>The resident has read and accepts the terms of service.</span></label></>}<label className="field"><span>Service area</span><select name="area_id" required defaultValue=""><option value="" disabled>Choose a managed area</option>{areas.map(a=><option key={a.id} value={a.id}>{a.locality}, {a.city}, {a.state}</option>)}</select></label><label className="field"><span>Address label</span><input name="label" required maxLength={80} placeholder="Home or shop"/></label><label className="field"><span>Street address</span><input name="address_line1" required maxLength={180}/></label><label className="field"><span>Apartment or suite</span><input name="address_line2" maxLength={180}/></label><label className="field"><span>Postal code</span><input name="postal_code" maxLength={24}/></label><label className="field"><span>Property type</span><select name="property_type"><option value="residential">Residential</option><option value="commercial">Commercial</option><option value="mixed_use">Mixed use</option><option value="other">Other</option></select></label><label className="field"><span>Structure</span><select name="structure_type"><option value="bungalow">Bungalow</option><option value="storey_building">Storey building</option><option value="apartment_block">Apartment block</option><option value="shop_complex">Shop complex</option><option value="mixed_use">Mixed use</option><option value="other">Other</option></select></label><label className="field"><span>Floors</span><input name="floors" type="number" min="1" max="100" defaultValue="1" required/></label><label className="field"><span>Registering</span><select name="registration_scope"><option value="whole_property">Whole property</option><option value="single_unit">One unit</option></select></label><label className="field"><span>Resident role</span><select name="registrant_role"><option value="owner">Owner</option><option value="tenant">Tenant</option><option value="caretaker">Caretaker</option><option value="agent">Agent</option></select></label><label className="field"><span>Unit type</span><select name="unit_type"><option value="residential">Residence</option><option value="shop">Shop</option><option value="office">Office</option><option value="shared">Shared</option><option value="other">Other</option></select></label><label className="field"><span>Bin arrangement</span><select name="service_scope"><option value="individual_bin">Individual bin per unit</option><option value="shared_bin">Shared property bin</option></select></label><label className="field"><span>Unit name(s)</span><input name="unit_codes" required placeholder="Downstairs | Ground floor, Upstairs | First floor"/><small>Separate units with commas. Add the floor after |.</small></label><button className="button" disabled={busy||areas.length===0}>{busy?'Saving…':'Save assisted registration'}</button></form></div></details>
     {requests.length>0&&<details className="panel disclosure-panel"><summary>Requests to join existing properties ({requests.length})</summary><div className="table-wrap"><table><thead><tr><th>Resident</th><th>Address</th><th>Requested unit</th><th>Role</th><th>Bin arrangement</th><th>Decision reason</th><th>Review</th></tr></thead><tbody>{requests.map(x=><tr key={x.id}><td>{x.resident}<br/><small>{x.phone}</small></td><td>{x.address}</td><td>{x.code}{x.floor_label?` · ${x.floor_label}`:''}</td><td>{statusLabel(x.relationship)}</td><td>{statusLabel(x.service_scope)}</td><td><textarea aria-label={`Reason for ${x.code}`} rows={2} maxLength={500} minLength={5} required value={reasons[x.id]||''} onChange={e=>setReasons(prev=>({...prev,[x.id]:e.target.value}))}/></td><td><button className="button button-small" disabled={busy} onClick={()=>reviewUnitRequest(x.id,'approved')}>Approve</button> <button className="button button-small button-outline" disabled={busy} onClick={()=>reviewUnitRequest(x.id,'rejected')}>Reject</button></td></tr>)}</tbody></table></div></details>}
    <section className="panel"><div className="panel-heading"><div><h2>Application queue</h2><p>{total.toLocaleString()} records · showing 25 per page · pending reviews first</p></div></div><form className="inline-form" onSubmit={e=>{e.preventDefault();setPage(1);setSearch(searchDraft.trim())}}><label className="field"><span>Search applications</span><input value={searchDraft} onChange={e=>setSearchDraft(e.target.value)} placeholder="Name, email, phone, address, or area"/></label><label className="field"><span>Review status</span><select value={statusFilter} onChange={e=>{setPage(1);setStatusFilter(e.target.value)}}><option value="">All statuses</option><option value="pending_review">Pending review</option><option value="awaiting_bin_delivery">Awaiting bin delivery</option><option value="verified">Verified</option><option value="rejected">Rejected</option></select></label><button className="button button-outline" type="submit">Search</button></form>{items.length===0?<div className="empty-inline">{total===0?'No applications match this view.':'No applications on this page.'}</div>:<div className="table-wrap"><table><thead><tr><th>Application</th><th>Resident</th><th>Service area</th><th>Property</th><th>Status</th><th>Units / bins</th><th>Submitted</th><th></th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td>#{x.id}</td><td>{x.resident}</td><td>{x.area}</td><td>{statusLabel(x.property_type)} · {statusLabel(x.structure_type)}</td><td><Status value={x.review_status}/></td><td>{x.unit_count} / {x.bin_count}</td><td>{new Date(x.created_at).toLocaleDateString()}</td><td><button className="link-button" disabled={busy} onClick={()=>openProperty(x.id)}>View application</button></td></tr>)}</tbody></table></div>}<div className="panel-heading"><span>Page {page} of {pageCount}</span><div><button className="button button-small button-outline" disabled={page<=1||busy} onClick={()=>setPage(p=>p-1)}>Previous</button> <button className="button button-small button-outline" disabled={page>=pageCount||busy} onClick={()=>setPage(p=>p+1)}>Next</button></div></div></section>
    {selected&&<section className="panel"><div className="panel-heading"><div><p className="eyebrow">Application #{selected.id}</p><h2>{selected.address}</h2><p>{statusLabel(selected.property_type)} · {statusLabel(selected.structure_type)} · {statusLabel(selected.registration_scope)} · {statusLabel(selected.registrant_role)}</p><p className="muted">Contact: {selected.resident} · {selected.phone} · {selected.email}</p><p>Units: {selected.units.map(u=>u.code).join(', ')||'No units'}</p></div><div><Status value={selected.review_status}/><p><button className="button button-small button-outline" onClick={()=>setSelected(null)}>Close details</button></p></div></div>
       <div className="panel-subsection"><h3>Application review</h3>{selected.review_reason&&<p>Decision reason: {selected.review_reason}</p>}{selected.review_status==='pending_review'?<><p className="muted">This application is waiting for a management decision. Enter a reason for either decision.</p><label className="field"><span>Review reason</span><textarea rows={2} minLength={5} maxLength={500} required value={applicationReasons[selected.id]||''} onChange={e=>setApplicationReasons(prev=>({...prev,[selected.id]:e.target.value}))}/></label><button className="button button-small" disabled={busy} onClick={()=>reviewApplication(selected.id,'approved')}>Accept and prepare bins</button> <button className="button button-small button-outline" disabled={busy} onClick={()=>reviewApplication(selected.id,'rejected')}>Reject application</button></>:selected.review_status==='awaiting_bin_delivery'?<p className="muted">Reviewed and accepted. Service is verified after all required bins are delivered.</p>:selected.review_status==='verified'?<p className="muted">Verified by recorded delivery of all required bins.</p>:<p className="muted">This application was rejected.</p>}</div>
       {selected.bins.length>0&&<div className="panel-subsection"><h3>Bin profiles</h3><div className="table-wrap"><table><thead><tr><th>Tracking ID and QR</th><th>Assigned unit</th><th>Resident account</th><th>Size</th><th>Status</th><th>Registered</th><th>Delivery confirmation</th><th>Last evacuation</th></tr></thead><tbody>{selected.bins.map(bin=><tr key={bin.id}><td><strong>{bin.tracking_id}</strong><BinQrLabel trackingId={bin.tracking_id}/></td><td>{bin.unit_code||'Shared property'}</td><td>{bin.assigned_resident||'Account needs assignment'}</td><td>{bin.size_litres} L</td><td>{statusLabel(bin.status)}</td><td>{new Date(bin.registered_at).toLocaleString()}</td><td>{bin.delivered_at?`${new Date(bin.delivered_at).toLocaleString()} · ${bin.delivered_by||'Staff'}${bin.delivery_note?` · ${bin.delivery_note}`:''}`:'Not delivered'}</td><td>{bin.last_evacuated_at?`${new Date(bin.last_evacuated_at).toLocaleString()}${bin.evacuated_by?` · ${bin.evacuated_by}`:''}`:'None recorded'}</td></tr>)}</tbody></table></div></div>}
       {selected.review_status==='awaiting_bin_delivery'&&['awaiting_bin_delivery','needs_review'].includes(selected.status)&&<form className="form-grid bin-handover-form" onSubmit={e=>handover(e,selected.id)}><h3>Register and hand over a bin</h3><p className="muted">The system assigns a unique tracking ID and creates its QR label after registration.</p><label className="field"><span>Bin capacity (litres)</span><input name="size_litres" type="number" min="1" step="1" required/></label><label className="field"><span>Assigned to unit</span><select name="unit_id" defaultValue="">{selected.units.some(u=>u.service_scope==='shared_bin')&&<option value="">Shared property bin</option>}{selected.units.filter(u=>u.service_scope==='individual_bin').map(u=><option key={u.id} value={u.id}>{u.code}</option>)}</select></label><label className="field"><span>Resident account email (optional)</span><input name="resident_email" type="email" placeholder="Confirm a different active unit resident"/></label><label className="field"><span>Handover result</span><select name="outcome"><option value="delivered">Delivered to resident</option><option value="failed">Could not deliver</option></select></label><label className="field"><span>Delivery note</span><input name="note" maxLength={500} placeholder="Optional delivery note"/></label><button className="button" disabled={busy}>{busy?'Recording…':'Register and record handover'}</button></form>}
    </section>}</>
}

function OperationsComplaints(){const[data,setData]=useState<Awaited<ReturnType<typeof api.operationsComplaints>>['items']>([]);const[error,setError]=useState('');const[filter,setFilter]=useState('');const[selected,setSelected]=useState<string|null>(null);const[status,setStatus]=useState('under_review');const[publicMessage,setPublicMessage]=useState('');const[internalNote,setInternalNote]=useState('');const[busy,setBusy]=useState(false);const load=()=>api.operationsComplaints(filter).then(x=>setData(x.items)).catch(e=>setError(e.message));useEffect(()=>{load()},[filter]);async function update(e:FormEvent){e.preventDefault();if(!selected)return;setBusy(true);setError('');try{await api.updateComplaint(selected,{status,public_message:publicMessage,internal_note:internalNote});setSelected(null);setPublicMessage('');setInternalNote('');await load()}catch(e){setError(e instanceof Error?e.message:'Status update failed')}finally{setBusy(false)}}return <><OpsTitle title="Resident complaints" description="Review reports and send clear progress updates to residents."/><OperationError message={error}/><section className="panel"><div className="panel-heading"><div><h2>Complaint queue</h2><p>Resident contact details are visible to authorized operations staff only.</p></div><select aria-label="Filter by status" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All statuses</option>{['submitted','under_review','assigned','in_progress','resolved','rejected'].map(x=><option key={x} value={x}>{statusLabel(x)}</option>)}</select></div>{data.length===0?<p className="empty-inline">No complaints match this view.</p>:<div className="table-wrap"><table><thead><tr><th>Reference</th><th>Resident</th><th>Issue</th><th>Location</th><th>Status</th><th></th></tr></thead><tbody>{data.map(x=><tr key={x.complaint.reference}><td>{x.complaint.reference}</td><td>{x.citizen.full_name}<br/><small>{x.citizen.phone}</small></td><td>{categoryLabel(x.complaint.category)}</td><td>{x.complaint.location}</td><td><Status value={x.complaint.status}/></td><td><button className="link-button" onClick={()=>{setSelected(x.complaint.reference);setStatus(x.complaint.status==='submitted'?'under_review':x.complaint.status)}}>Update</button></td></tr>)}</tbody></table></div>}</section>{selected&&<div className="modal-backdrop" role="presentation"><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="update-title"><button className="modal-close" onClick={()=>setSelected(null)} aria-label="Close">×</button><p className="eyebrow">{selected}</p><h2 id="update-title">Update complaint</h2><form className="form-stack" onSubmit={update}><label className="field"><span>Status</span><select value={status} onChange={e=>setStatus(e.target.value)}>{['under_review','assigned','in_progress','resolved','rejected'].map(x=><option key={x} value={x}>{statusLabel(x)}</option>)}</select></label><label className="field"><span>Message for resident</span><textarea rows={3} maxLength={1000} value={publicMessage} onChange={e=>setPublicMessage(e.target.value)} placeholder="Optional update visible to the resident"/></label><label className="field"><span>Internal note</span><textarea rows={3} maxLength={2000} value={internalNote} onChange={e=>setInternalNote(e.target.value)} placeholder="Staff only"/></label><button className="button" disabled={busy}>{busy?'Saving…':'Save update'}</button></form></section></div>}</>}


function OperationsCollections(){const[data,setData]=useState<Awaited<ReturnType<typeof api.collections>>['collections']>([]);const[containers,setContainers]=useState<Awaited<ReturnType<typeof api.containers>>['containers']>([]);const[staff,setStaff]=useState<{id:number;full_name:string}[]>([]);const[error,setError]=useState('');const load=()=>api.collections().then(x=>setData(x.collections)).catch(e=>setError(e.message));useEffect(()=>{load();api.containers().then(x=>setContainers(x.containers)).catch(e=>setError(e.message));api.operationsStaff().then(x=>setStaff(x.staff)).catch(e=>setError(e.message))},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);try{await api.createCollection({container_id:String(d.get('container_id')),assigned_to:Number(d.get('assigned_to')),scheduled_at:new Date(String(d.get('scheduled_at'))).toISOString()});e.currentTarget.reset();load()}catch(e){setError(e instanceof Error?e.message:'Could not create collection')}}async function update(id:number,status:string){try{await api.updateCollection(id,{status,completion_note:''});load()}catch(e){setError(e instanceof Error?e.message:'Update failed')}}return <><OpsTitle title="Collection jobs" description="Schedule and track waste collection work."/><OperationError message={error}/><section className="panel"><h2>Schedule collection</h2><form className="inline-form" onSubmit={submit}><label className="field"><span>Container</span><select name="container_id" required defaultValue=""><option value="" disabled>Select container</option>{containers.map(c=><option key={c.id} value={c.id}>{c.label} · {c.service_area}</option>)}</select></label><label className="field"><span>Assign to</span><select name="assigned_to" defaultValue="0"><option value="0">Unassigned</option>{staff.map(x=><option key={x.id} value={x.id}>{x.full_name}</option>)}</select></label><Field label="Scheduled time" name="scheduled_at" type="datetime-local" required/><button className="button">Create job</button></form></section><section className="panel"><h2>Scheduled and recent jobs</h2>{data.length===0?<p className="empty-inline">No collection jobs yet.</p>:<div className="table-wrap"><table><thead><tr><th>Job</th><th>Container</th><th>Scheduled</th><th>Assigned to</th><th>Status</th><th>Update</th></tr></thead><tbody>{data.map(x=><tr key={x.id}><td>#{x.id}</td><td>{x.container_label}</td><td>{new Date(x.scheduled_at).toLocaleString()}</td><td>{x.assigned_name}</td><td><Status value={x.status}/></td><td><select aria-label={`Update job ${x.id}`} value={x.status} onChange={e=>update(x.id,e.target.value)}>{['scheduled','assigned','in_progress','completed','cancelled'].map(s=><option key={s} value={s}>{statusLabel(s)}</option>)}</select></td></tr>)}</tbody></table></div>}</section></>}

function OperationsInspections(){const[data,setData]=useState<Awaited<ReturnType<typeof api.inspections>>['inspections']>([]);const[containers,setContainers]=useState<Awaited<ReturnType<typeof api.containers>>['containers']>([]);const[error,setError]=useState('');const load=()=>api.inspections().then(x=>setData(x.inspections)).catch(e=>setError(e.message));useEffect(()=>{load();api.containers().then(x=>setContainers(x.containers)).catch(e=>setError(e.message))},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);try{await api.createInspection({container_id:String(d.get('container_id')),condition:String(d.get('condition')),notes:String(d.get('notes'))});e.currentTarget.reset();load()}catch(e){setError(e instanceof Error?e.message:'Inspection could not be saved')}}return <><OpsTitle title="Inspections" description="Record the observed condition of a registered container."/><OperationError message={error}/><section className="panel"><h2>Record inspection</h2><form className="inline-form" onSubmit={submit}><label className="field"><span>Container</span><select name="container_id" required defaultValue=""><option value="" disabled>Select container</option>{containers.map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select></label><label className="field"><span>Condition</span><select name="condition"><option value="good">Good</option><option value="needs_attention">Needs attention</option><option value="damaged">Damaged</option><option value="missing">Missing</option></select></label><Field label="Notes" name="notes" required={false}/><button className="button">Save inspection</button></form></section><section className="panel"><h2>Recent inspections</h2>{data.length===0?<p className="empty-inline">No inspections have been recorded.</p>:data.map(x=><article className="notice-row" key={x.id}><span className="notice-icon">◉</span><div><strong>{x.container_label}</strong> · <Status value={x.condition}/><p>{x.notes||'No additional notes.'}</p><small>{x.inspector} · {new Date(x.inspected_at).toLocaleString()}</small></div></article>)}</section></>}

function OperationsAnalytics(){const[data,setData]=useState<Awaited<ReturnType<typeof api.analytics>>|null>(null);const[error,setError]=useState('');useEffect(()=>{api.analytics().then(setData).catch(e=>setError(e.message))},[]);const trends=data?.weekly_trends||[];const max=Math.max(1,...trends.flatMap(x=>[x.complaints_opened,x.complaints_resolved,x.collections_completed]));return <><OpsTitle title="Operational analytics" description="Service indicators and weekly trends from stored operational records."/><OperationError message={error}/><div className="stat-grid">{[['Registered containers','registered_containers'],['Devices offline','offline_devices'],['Active complaints','active_complaints'],['Overdue collections','overdue_collections'],['Completed in 30 days','completed_collections_30d']].map(([label,key])=><Stat key={key} label={label} value={String(data?.[key as keyof typeof data]??'—')} icon="◷"/>)}<Stat label="Avg. resolution (30d)" value={data?.average_resolution_hours_30d==null?'—':`${data.average_resolution_hours_30d.toFixed(1)} hrs`} icon="◷" note="Based on first recorded resolved update"/></div><section className="panel"><div className="panel-heading"><div><h2>Weekly service activity</h2><p>Eight weeks of complaint and collection activity.</p></div></div>{trends.length===0?<div className="empty-inline">No dated activity is available yet.</div>:<><div className="trend-legend"><span><i className="trend-opened"/>Complaints opened</span><span><i className="trend-resolved"/>Complaints resolved</span><span><i className="trend-collections"/>Collections completed</span></div><div className="trend-chart" role="img" aria-label="Grouped bar chart of weekly complaints opened, complaints resolved, and completed collections">{trends.map(w=><div className="trend-week" key={w.week}><div className="trend-bars">{([[w.complaints_opened,'trend-opened'],[w.complaints_resolved,'trend-resolved'],[w.collections_completed,'trend-collections']] as [number,string][]).map(([value,color],i)=><div key={i} className={`trend-bar ${color}`} style={{height:`${Math.max(value?4:0,value/max*100)}%`}} title={String(value)} aria-label={String(value)}/>)}</div><small>{new Date(`${w.week}T00:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small></div>)}</div></>}</section></>}

function OperationsAlerts(){const[data,setData]=useState<Awaited<ReturnType<typeof api.notifications>>['notifications']>([]);const[error,setError]=useState('');useEffect(()=>{api.notifications().then(x=>setData(x.notifications)).catch(e=>setError(e.message))},[]);return <><OpsTitle title="Operational alerts" description="Notifications generated from recorded service events."/><OperationError message={error}/><section className="panel">{data.length===0?<div className="empty-panel"><span className="empty-icon">⚑</span><h2>No active notifications</h2><p>Alerts will appear as verified sensor or operational events are recorded.</p></div>:data.map(x=><article className="notice-row" key={x.id}><span className="notice-icon">⚑</span><div><strong>{x.title}</strong><p>{x.message}</p><small>{new Date(x.created_at).toLocaleString()}</small></div></article>)}</section></>}

function OperationsAnnouncements(){const[data,setData]=useState<Awaited<ReturnType<typeof api.announcements>>['announcements']>([]);const[error,setError]=useState('');const load=()=>api.announcements(true).then(x=>setData(x.announcements)).catch(e=>setError(e.message));useEffect(()=>{load()},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);try{await api.createAnnouncement({title:String(d.get('title')),body:String(d.get('body')),status:String(d.get('status'))});e.currentTarget.reset();load()}catch(e){setError(e instanceof Error?e.message:'Announcement could not be saved')}}return <><OpsTitle title="Service announcements" description="Draft or publish clear notices for residents."/><OperationError message={error}/><section className="panel"><h2>Write announcement</h2><form className="form-stack compact-form" onSubmit={submit}><Field label="Title" name="title" required/><label className="field"><span>Message</span><textarea name="body" minLength={10} maxLength={10000} rows={4} required/></label><label className="field"><span>Publication</span><select name="status"><option value="draft">Save draft</option><option value="published">Publish now</option></select></label><button className="button">Save announcement</button></form></section><section className="panel"><h2>Announcements</h2>{data.length===0?<p className="empty-inline">No announcements have been created.</p>:data.map(x=><article className="announcement-row" key={x.id}><div><Status value={x.status}/><h3>{x.title}</h3><p>{x.body}</p><small>{x.author} · {new Date(x.created_at).toLocaleString()}</small></div></article>)}</section></>}

function AdminStaff(){const[data,setData]=useState<Awaited<ReturnType<typeof api.staff>>['staff']>([]);const[error,setError]=useState('');const load=()=>api.staff().then(x=>setData(x.staff)).catch(e=>setError(e.message));useEffect(()=>{load()},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const d=new FormData(form);try{await api.createStaff({full_name:String(d.get('full_name')),email:String(d.get('email')),phone:String(d.get('phone')),password:String(d.get('password')),role:String(d.get('role'))});form.reset();load()}catch(e){setError(e instanceof Error?e.message:'Staff account could not be created')}}async function change(id:number,role:string,active:boolean){try{await api.updateStaff(id,{role,active});load()}catch(e){setError(e instanceof Error?e.message:'Access update failed')}}return <><OpsTitle title="Staff and roles" description="Create operational accounts and maintain their assigned access."/><OperationError message={error}/><section className="panel"><h2>Create staff account</h2><form className="inline-form" onSubmit={submit}><Field label="Full name" name="full_name" required/><Field label="Email" name="email" type="email" required/><Field label="Phone" name="phone" type="tel" required/><PasswordField label="Temporary password" name="password" autoComplete="new-password" minLength={14} required/><label className="field"><span>Role</span><select name="role"><option value="operations_manager">Operations manager</option><option value="system_administrator">System administrator</option></select></label><button className="button">Create account</button></form><p className="form-hint muted">Share the initial password through an approved secure channel. Email invitations are not configured.</p></section><section className="panel"><h2>Staff accounts</h2>{data.length===0?<p className="empty-inline">No staff accounts have been created.</p>:<div className="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Role</th><th>Access</th><th>Action</th></tr></thead><tbody>{data.map(x=><tr key={x.id}><td>{x.full_name}</td><td>{x.email}</td><td>{x.phone}</td><td><select value={x.role} onChange={e=>change(x.id,e.target.value,x.active)}><option value="operations_manager">Operations manager</option><option value="system_administrator">System administrator</option></select></td><td><Status value={x.active?'active':'inactive'}/></td><td><button className="button button-small button-outline" onClick={()=>change(x.id,x.role,!x.active)}>{x.active?'Disable':'Reactivate'}</button></td></tr>)}</tbody></table></div>}</section></>}



function AdminAuditLogs(){const[data,setData]=useState<Awaited<ReturnType<typeof api.auditLogs>>['audit_logs']>([]);const[error,setError]=useState('');useEffect(()=>{api.auditLogs().then(x=>setData(x.audit_logs)).catch(e=>setError(e.message))},[]);return <><OpsTitle title="Audit logs" description="Review recorded privileged changes."/><OperationError message={error}/><section className="panel">{data.length===0?<p className="empty-inline">No audit events have been recorded.</p>:<div className="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Resource</th><th>Reference</th></tr></thead><tbody>{data.map(x=><tr key={x.id}><td>{new Date(x.created_at).toLocaleString()}</td><td>{x.actor}</td><td>{x.action}</td><td>{x.resource_type}</td><td>{x.resource_id}</td></tr>)}</tbody></table></div>}</section></>}

function AdminSettings(){const[data,setData]=useState<Record<string,number>>({});const[error,setError]=useState('');const[message,setMessage]=useState('');useEffect(()=>{api.settings().then(x=>setData(x.settings)).catch(e=>setError(e.message))},[]);async function save(e:FormEvent){e.preventDefault();try{await api.updateSettings(data);setMessage('Settings saved.');setError('')}catch(e){setError(e instanceof Error?e.message:'Settings could not be saved')}}const set=(key:string,value:string)=>setData(prev=>({...prev,[key]:Number(value)}));return <><OpsTitle title="Platform settings" description="Configure initial sensor alert thresholds and offline timing."/><OperationError message={error}/>{message&&<p className="success-message">{message}</p>}<section className="panel settings-panel"><form className="form-stack" onSubmit={save}><label className="field"><span>Warning threshold (%)</span><input type="number" min="1" max="99" value={data.fill_warning_threshold??70} onChange={e=>set('fill_warning_threshold',e.target.value)}/></label><label className="field"><span>Critical threshold (%)</span><input type="number" min="2" max="100" value={data.fill_critical_threshold??90} onChange={e=>set('fill_critical_threshold',e.target.value)}/></label><label className="field"><span>Offline after (minutes)</span><input type="number" min="5" max="10080" value={data.offline_after_minutes??180} onChange={e=>set('offline_after_minutes',e.target.value)}/></label><button className="button">Save settings</button></form></section></>}

function Status({value}:{value:string}){return <span className={`status status-${value}`}>{statusLabel(value)}</span>}
function statusLabel(value:string){return value.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase())}
function categoryLabel(value:string){return ({overflowing_skip:'Overflowing waste skip',missed_collection:'Missed collection',illegal_dumping:'Illegal dumping',other:'Other sanitation issue'} as Record<string,string>)[value]||value}
function Loading(){return <div className="loading" role="status"><span className="spinner"/>Loading…</div>}
function NotFound(){return <section className="page-wrap"><p className="eyebrow">Not found</p><h1>This page isn’t available.</h1><Link to="/" className="button">Return home</Link></section>}

export default App
